def frames(s):
    """Return list of (frame, codon_list) for 3 forward frames."""
    out=[]
    for f in range(3):
        cods=[s[i:i+3] for i in range(f, len(s)-2, 3)]
        out.append((f,cods))
    return out

def report(s, strand):
    """strand '+' or '-'; print stop-free runs >=100 codons with in-frame starts."""
    print("=== strand", strand, "===")
    for f, cods in frames(s):
        # stop positions as 0-based index into cods
        stop_idx=[j for j,cd in enumerate(cods) if ct.get(cd)=='*']
        edges=[-1]+stop_idx+[len(cods)]
        for a,b in zip(edges[:-1],edges[1:]):
            n=b-a-1
            if n>=100:
                # starts within codon range a+1 .. b-1
                starts=[]
                for j in range(a+1,b):
                    if cods[j] in ('ATG','GTG','TTG'):
                        starts.append((j, cods[j], (b-j)))  # idx, start codon, aa length incl stop
                pos0 = lambda j: f+3*j   # 0-based coordinate in s
                lo, hi = pos0(a+1), pos0(b)+2
                if strand=='+':
                    g = (lo+1, hi+1)
                else:
                    g = (L-hi, L-lo)  # genomic span (lo..hi are 0-based in s=rc)
                print("frame %d: stop-free %d codons, coords %d..%d (genomic)" % (f, n, g[0], g[1]))
                if starts:
                    for j,sc,aa in starts[:12]:
                        p=pos0(j)
                        if strand=='+': gs=p+1
                        else: gs=L-p  # genomic 5' end of start codon
                        print("    start %s at genomic %d -> ORF of %d aa" % (sc, gs, aa-1))
                else:
                    print("    (no ATG/GTG/TTG start in frame)")

